<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {getRealJob,stopTraining,resumeTraining,realLabels} from '../api/training'
import type {RealJob} from '../api/training'
import MetricChart from '../components/charts/MetricChart.vue'
const route=useRoute(),router=useRouter(),job=ref<RealJob|null>(null),error=ref(''),busy=ref(false),resumeStep=ref(0),total=ref(100)
let timer:ReturnType<typeof setTimeout>,disposed=false
async function refresh(){const id=String(route.params.id);try{const value=await getRealJob(id);if(disposed||id!==String(route.params.id))return;const first=job.value?.id!==value.id;job.value=value;if(first||!value.checkpoints.some(c=>c.step===resumeStep.value)){resumeStep.value=value.checkpoints[value.checkpoints.length-1]?.step??0;total.value=Math.max(value.steps+20,resumeStep.value+20)}error.value=''}catch(e){error.value=String(e)}finally{if(!disposed&&id===String(route.params.id))timer=setTimeout(refresh,2000)}}
onMounted(refresh);watch(()=>route.params.id,()=>{clearTimeout(timer);job.value=null;void refresh()});onBeforeUnmount(()=>{disposed=true;clearTimeout(timer)})
async function stop(){busy.value=true;try{await stopTraining(String(route.params.id))}catch(e){error.value=String(e)}finally{busy.value=false}}
async function resume(){busy.value=true;try{const next=await resumeTraining(String(route.params.id),resumeStep.value,total.value);await router.push('/real-jobs/'+next.id)}catch(e){error.value=String(e)}finally{busy.value=false}}
const option=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'value',name:'Step'},yAxis:{type:'value',name:'Loss'},series:[{type:'line',showSymbol:false,data:job.value?.metrics.map(p=>[p.step,p.loss])??[]}]}))
</script>
<template><div class="page-heading"><div><h1>{{job?.name||'真实训练监控'}}</h1><p>真实进程 · 不生成模拟 Loss 或 GPU 指标</p></div><button class="button" @click="router.push('/real-jobs')">返回队列</button><button v-if="job&&['Queued','Starting','Running','Stopping'].includes(job.status)" class="button danger" :disabled="busy" @click="stop">停止任务</button></div><p v-if="error||job?.error" class="form-error">{{error||job?.error}}</p><template v-if="job"><div class="stat-strip"><div class="strip-item"><span>状态</span><strong>{{realLabels[job.status]}}</strong></div><div class="strip-item"><span>Step</span><strong>{{job.step}} / {{job.steps}}</strong></div><div class="strip-item"><span>Loss</span><strong>{{job.loss??'—'}}</strong></div><div class="strip-item"><span>运行秒数</span><strong>{{job.elapsed??0}}</strong></div></div><section class="panel content-panel"><h2>输出目录</h2><p style="overflow-wrap:anywhere">{{job.outputDir||job.config?.outputDir||job.config?.configPath||'旧版任务：请查看下方配置及 Checkpoint 路径'}}</p><p v-if="job.config?.resumeParent">续训来源：{{job.config.resumeParent.jobId}} · Step {{job.config.resumeParent.step}}</p></section><section class="panel content-panel"><h2>真实 Loss</h2><MetricChart :option="option"/></section><section class="panel content-panel"><h2>训练日志（最近 300 行）</h2><pre class="log-terminal">{{job.logs.join('\n')||'等待进程输出…'}}</pre><p>完整日志保存在任务目录的 training.log。</p></section><section class="panel content-panel"><h2>已保存 Checkpoints</h2><p>仅登记数字目录中同时存在模型、优化器和元数据文件的 PyTorch 快照。临时目录不显示。</p><div v-for="cp in job.checkpoints" :key="cp.step" class="setting-row"><span>Step {{cp.step}}<small>{{cp.path}}</small></span></div><div v-if="!['Queued','Starting','Running','Stopping'].includes(job.status)&&job.checkpoints.length" class="form-grid" style="grid-template-columns:1fr"><label>续训起点<select v-model.number="resumeStep"><option v-for="cp in job.checkpoints" :key="cp.step" :value="cp.step">{{cp.step}}</option></select></label><label>新的总步数<input v-model.number="total" type="number" :min="resumeStep+1"/></label><button class="button" :disabled="busy||total<=resumeStep" @click="resume">复制该快照并创建续训任务</button><small>使用新任务输出目录，保留原任务；复制大型 Checkpoint 需要时间和磁盘空间。</small></div></section><details class="info-note"><summary>实际执行配置</summary><pre class="command-preview">{{JSON.stringify(job.config,null,2)}}</pre></details></template></template>
